// Contrôles de sécurité d'une action envoyée par le tableau de bord
const req = $input.first().json;
const h = req.headers ?? {};
const b = req.body ?? {};
const refus = message => [{ json: { sortie: 2, message } }];

// 1. Anti DNS rebinding : uniquement les adresses locales
if (!/^(localhost|127\.0\.0\.1)(:\d+)?$/.test(String(h.host ?? ''))) return refus('Hôte non autorisé.');
// 2. Origine : absente, « null » (page en bac à sable n8n) ou locale. Un autre site est refusé.
const origine = String(h.origin ?? '');
if (origine && !/^(null|https?:\/\/(localhost|127\.0\.0\.1)(:\d+)?)$/.test(origine)) return refus('Origine refusée.');
// 3. Jeton anti-CSRF : doit exister, ne pas être expiré, et ne sert qu'une fois
const mem = $getWorkflowStaticData('global');
const jeton = String(b.jeton ?? '');
if (!jeton || !mem.jetons?.[jeton] || mem.jetons[jeton] < Date.now()) return refus('Formulaire expiré : recharge la page et recommence.');
delete mem.jetons[jeton];
// 4. Liste blanche d'actions et paramètres stricts
const ACTIONS = ['rediger', 'modifier', 'valider', 'envoyer', 'annuler', 'ignorer', 'nonlu', 'restaurer', 'verifier', 'veille'];
const action0 = String(b.action ?? '');
// « veille » : lance la veille cyber (envoi Telegram + Discord), sans paramètre
if (action0 === 'veille') return [{ json: { sortie: 4, action: 'veille' } }];
// « resumer » : fiche de synthèse d'une CVE (la CVE est dans le champ « id »)
if (action0 === 'resumer') {
  const cve = String(b.id ?? '').toUpperCase();
  if (!/^CVE-\d{4}-\d{4,7}$/.test(cve)) return refus('Identifiant CVE invalide.');
  return [{ json: { sortie: 5, action: 'resumer', cve, kev: String(b.compte ?? '') === 'K' } }];
}
// « verifier » : lance la surveillance des mails, sans paramètre
if (action0 === 'verifier') return [{ json: { sortie: 3, action: 'verifier' } }];
const action = String(b.action ?? '');
const id = String(b.id ?? '');
const compte = String(b.compte ?? '');
if (!ACTIONS.includes(action) || !/^[0-9a-f]{8,32}$/i.test(id)) return refus('Demande invalide.');
// « ignorer » et « nonlu » ne concernent que le tableau de bord : aucun compte n'est touché
if (!['ignorer', 'nonlu', 'restaurer'].includes(action) && !['P', 'C', 'J'].includes(compte)) return refus('Demande invalide.');
if (action === 'restaurer') {
  if (mem.ignores) delete mem.ignores[id];
  return [{ json: { sortie: 1, action, id, message: 'Remis dans la liste.' } }];
}
if (action === 'nonlu') {
  if (mem.lus) delete mem.lus[id];
  return [{ json: { sortie: 1, action, id, message: 'Marqué comme non lu.' } }];
}
if (action === 'ignorer') {
  mem.ignores = Object.fromEntries(Object.entries(mem.ignores ?? {}).filter(([, t]) => Date.now() - t < 7 * 24 * 3600 * 1000));
  mem.ignores[id] = Date.now();
  return [{ json: { sortie: 1, action, id, message: 'Retiré de la liste (rien n\'a été modifié dans ta boîte mail).' } }];
}
return [{ json: { sortie: 0, action, id, compte, instructions: String(b.instructions ?? '').slice(0, 2000), canal: 'web' } }];

// Retour sur la page « À traiter » avec un message
let message = '';
try { message = $('Vérifier la demande').first().json.message ?? ''; } catch {}
try {
  const r = $('Exécuter l\'action').first().json;
  if (r.error) message = 'Échec : ' + String(r.error.message ?? r.error).slice(0, 150);
  else if (r.message) message = r.message.split('\n').filter(Boolean).slice(0, 2).join(' · ');
} catch {}
const action = (() => { try { return $('Vérifier la demande').first().json.action; } catch { return ''; } })();
if (!message) message = { rediger: 'Proposition prête.', modifier: 'Nouvelle version prête.', annuler: 'Réponse abandonnée.' }[action] ?? 'C\'est fait.';
// Mail envoyé ou brouillon créé : il passe en « répondu » dans le tableau
let id = '';
try { id = $('Vérifier la demande').first().json.id ?? ''; } catch {}
const mem = $getWorkflowStaticData('global');
mem.repondus ??= {};
if (id && action === 'envoyer' && message.startsWith('📤')) mem.repondus[id] = { type: 'envoye', date: Date.now() };
if (id && action === 'valider' && message.startsWith('✅')) mem.repondus[id] = { type: 'brouillon', date: Date.now() };
// Retour sur le mail concerné (sauf s'il vient d'être retiré ou remis en non lu)
if (action === 'verifier') {
  let n = 0;
  try { n = $('Vérifier les mails').all().filter(i => i.json.ok).length; } catch {}
  message = n ? `${n} nouveau${n > 1 ? 'x' : ''} mail${n > 1 ? 's' : ''} important${n > 1 ? 's' : ''}.` : 'Aucun nouveau mail important (seuls les mails « importants » pour Gmail et ceux de l\'école sont suivis).';
}
if (action === 'resumer') {
  const cve = (() => { try { return $('Vérifier la demande').first().json.cve; } catch { return ''; } })();
  let err = null;
  try { err = $('Résumer la CVE').first().json; } catch {}
  const m = err?.erreur ? 'Résumé impossible : ' + String(err.erreur).slice(0, 150) : '';
  return [{ json: { location: '/webhook/tableau?page=veille&resume=' + encodeURIComponent(cve) + (m ? '&msg=' + encodeURIComponent(m) : '') + '#fiche' } }];
}
if (action === 'veille') {
  let erreur = null;
  try { erreur = $('Lancer la veille').all().find(i => i.json.error)?.json.error; } catch {}
  message = erreur ? 'Échec de la veille : ' + String(erreur.message ?? erreur).slice(0, 150)
                   : 'Veille lancée : les nouveautés éventuelles sont parties sur Telegram et Discord.';
  return [{ json: { location: '/webhook/tableau?page=veille&forcer=1&msg=' + encodeURIComponent(message) } }];
}
const voir = id && !['ignorer', 'nonlu', 'restaurer'].includes(action) ? '&voir=' + encodeURIComponent(id) : '';
return [{ json: { location: '/webhook/tableau?page=traiter' + voir + '&msg=' + encodeURIComponent(message.slice(0, 280)) } }];
